INSERT INTO `products` VALUES
(1,'SKU-001','Πλεκτό Κουνελάκι','Crochet Bunny',NULL,NULL,0,31.5,12,'discontinued',0,1,NULL,'Animals',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(2,'SKU-002','Βρεφική Κουβέρτα','Baby Blanket',NULL,NULL,0,65,20,'discontinued',0,0,NULL,'Blankets',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(4,'SKU-004','Μπουκέτο Λουλουδιών','Flower Bouquet',NULL,NULL,0,42,15,'discontinued',0,1,NULL,'Decor',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
(6,'ATH-REAL-BEE','Βελούδινο Μελισσάκι','Bumble Bee Plushie','Αυτό το χειροποίητο μελισσάκι χαρίζει χαρούμενη διάθεση με τη βελούδινη υφή του και το παιχνιδιάρικο σχήμα του.\n\n\n\nΕίναι μια γλυκιά χειροποίητη ιδέα για δώρο και ένας όμορφος μικρός σύντροφος για ράφια, κρεβάτια ή αγκαλιές.\n\n\n\nΕπιλογή προσαρμογής: μπορείτε να αλλάξετε το χρώμα 1 και το χρώμα 2 κατόπιν συνεννόησης.\n\n\n\nΥλικό: Νήμα velvet.\n\n\n\nΣημαντικό: Τα μικρά κομμάτια και τα ματάκια σε αυτό το λούτρινο απαιτούν επίβλεψη από γονείς για μωρά και μικρά παιδιά.\n\n\n\nΑποποίηση ευθύνης: Οι φωτογραφίες αποτελούν μια κατά προσέγγιση απεικόνιση του τελικού χρώματος. Λόγω διαφορών στα υλικά, στις ρυθμίσεις των ψηφιακών οθονών και στις παραλλαγές παραγωγής, δεν μπορούμε να εγγυηθούμε ότι το χρώμα που βλέπετε στην οθόνη σας είναι ακριβώς το πραγματικό χρώμα του προϊόντος.','This handmade bumble bee plushie brings a bright, happy feel with its soft velvet finish and playful shape.\n\n\n\nIt makes a sweet handmade gift and a cozy little companion for shelves, beds, or cuddle time.\n\n\n\nChoose your favourite ready-made bee colourway from the gallery.\n\n\n\nMaterial: Velvet yarn.\n\n\n\nImportant: Small pieces and safety eyes on this plushie require parent supervision for babies and small children.\n\n\n\nDisclaimer: Our listing photos are an approximate representation of the final color. Due to substrate differences, digital screen settings, and production variations, we cannot guarantee the color you see on your screen is the true color of the product.',3,20,8,'low_stock',1,0,NULL,'Plushies',0,'Selected colourway','','Επιλεγμένος χρωματικός συνδυασμός','','','',NULL,NULL,NULL),
(7,'ATH-REAL-WHALE','Βελούδινο Φαλαινάκι','Velvet Whale Plushie','Ένα υπερ-μαλακό χειροποίητο φαλαινάκι με ήρεμη θαλασσινή αισθητική και βελούδινη υφή για αγκαλιές.\n\n\n\nΥπέροχο χειροποίητο δώρο για λάτρεις της θάλασσας και όμορφη διακοσμητική πινελιά για παιδικό ή υπνοδωμάτιο.\n\n\n\nΔιαθέσιμα μεγέθη και τιμές: Small €5, Medium €20, Large €50.\n\n\n\nΕπιλογή προσαρμογής: μπορείτε να διαλέξετε το χρώμα 1 και το μέγεθος που προτιμάτε.\n\n\n\nΥλικό: Νήμα velvet.\n\n\n\nΣημαντικό: Τα μικρά κομμάτια και τα ματάκια σε αυτό το λούτρινο απαιτούν επίβλεψη από γονείς για μωρά και μικρά παιδιά.\n\n\n\nΑποποίηση ευθύνης: Οι φωτογραφίες αποτελούν μια κατά προσέγγιση απεικόνιση του τελικού χρώματος. Λόγω διαφορών στα υλικά, στις ρυθμίσεις των ψηφιακών οθονών και στις παραλλαγές παραγωγής, δεν μπορούμε να εγγυηθούμε ότι το χρώμα που βλέπετε στην οθόνη σας είναι ακριβώς το πραγματικό χρώμα του προϊόντος.','A super soft handmade whale plushie with a calming ocean feel and a cuddly velvet texture.\n\n\n\nA beautiful handmade gift for sea-life lovers and a charming decor piece for nursery or bedroom shelves.\n\n\n\nAvailable sizes and prices: Small €5, Medium €20, Large €50.\n\n\n\nChoose your preferred size and pick one of the pictured whale colourways.\n\n\n\nMaterial: Velvet yarn.\n\n\n\nImportant: Small pieces and safety eyes on this plushie require parent supervision for babies and small children.\n\n\n\nDisclaimer: Our listing photos are an approximate representation of the final color. Due to substrate differences, digital screen settings, and production variations, we cannot guarantee the color you see on your screen is the true color of the product.',4,5,9,'active',0,1,NULL,'Plushies',0,'Selected colour','','Επιλεγμένο χρώμα','','','',NULL,NULL,NULL),
(8,'ATH-REAL-FROG-LEGS','Βατραχάκι με Ποδαράκια','Frog with Dangly Legs Plushie','Ένας χειροποίητος βάτραχος με μακριά ποδαράκια, απαλή βελούδινη υφή και παιχνιδιάρικη έκφραση.\n\n\n\nΙδανικός για χαρούμενο δώρο, για ράφι ή για αγκαλιές από όσους αγαπούν τα whimsical χειροποίητα λούτρινα.\n\n\n\nΕπιλογή προσαρμογής: το χρώμα 1 μπορεί να αλλάξει κατόπιν συνεννόησης.\n\n\n\nΥλικό: Νήμα velvet.\n\n\n\nΣημαντικό: Τα μικρά κομμάτια και τα ματάκια σε αυτό το λούτρινο απαιτούν επίβλεψη από γονείς για μωρά και μικρά παιδιά.\n\n\n\nΑποποίηση ευθύνης: Οι φωτογραφίες αποτελούν μια κατά προσέγγιση απεικόνιση του τελικού χρώματος. Λόγω διαφορών στα υλικά, στις ρυθμίσεις των ψηφιακών οθονών και στις παραλλαγές παραγωγής, δεν μπορούμε να εγγυηθούμε ότι το χρώμα που βλέπετε στην οθόνη σας είναι ακριβώς το πραγματικό χρώμα του προϊόντος.','A handmade frog plushie with extra-long dangling legs, soft velvet texture, and a playful expression.\n\n\n\nLovely as a cheerful gift, shelf buddy, or cuddle companion for anyone who loves whimsical handmade toys.\n\n\n\nAvailable in the playful frog colourways shown in the gallery.\n\n\n\nMaterial: Velvet yarn.\n\n\n\nImportant: Small pieces and safety eyes on this plushie require parent supervision for babies and small children.\n\n\n\nDisclaimer: Our listing photos are an approximate representation of the final color. Due to substrate differences, digital screen settings, and production variations, we cannot guarantee the color you see on your screen is the true color of the product.',4,12,5,'active',1,0,NULL,'Plushies',0,'Selected colour','','Επιλεγμένο χρώμα','','','',NULL,NULL,NULL),
(9,'ATH-REAL-BLANKETS','Παιδική Puffy Κουβέρτα','Puffy Kids Blanket','Μια πολύ μαλακή χειροποίητη παιδική κουβέρτα από puffy νήμα, ιδανική για αγκαλιές, βόλτες με το καρότσι, ύπνο και γλυκά όνειρα.\n\n\n\nΔιαθέσιμα μεγέθη και τιμές: Κουβέρτα Νεογέννητου (45x45εκ) €20, Κουβέρτα Αγκαλιάς (110x110εκ) €30, Κουβέρτα Καροτσιού (95x75εκ) €50, Κουβέρτα Κούνιας (150x110εκ) €70.\n\n\n\nΔιαθέσιμη σε όμορφους χρωματικούς συνδυασμούς και ιδανική ως προσεγμένο δώρο για μωρό.\n\n\n\nΥλικό: Puffy νήμα.\n\n\n\nΑποποίηση ευθύνης: Οι φωτογραφίες αποτελούν μια κατά προσέγγιση απεικόνιση του τελικού χρώματος. Λόγω διαφορών στα υλικά, στις ρυθμίσεις των ψηφιακών οθονών και στις παραλλαγές παραγωγής, δεν μπορούμε να εγγυηθούμε ότι το χρώμα που βλέπετε στην οθόνη σας είναι ακριβώς το πραγματικό χρώμα του προϊόντος.','A super-soft handmade kids blanket made with puffy yarn for cozy cuddles, stroller walks, nap time, and sweet dreams.\n\n\n\nAvailable sizes and prices: Newborn Blanket (45x45cm) €20, Receiving Blanket (110x110cm) €30, Stroller Blanket (95x75cm) €50, Crib Blanket (150x110cm) €70.\n\n\n\nChoose from the ready-made colour blends in the gallery and pair them with the blanket size that suits your little one best.\n\n\n\nMaterial: Puffy yarn.\n\n\n\nDisclaimer: Our listing photos are an approximate representation of the final color. Due to substrate differences, digital screen settings, and production variations, we cannot guarantee the color you see on your screen is the true color of the product.',4,20,14,'active',1,1,NULL,'Blankets',0,'Selected colourway','','Επιλεγμένος χρωματικός συνδυασμός','','','',NULL,NULL,NULL),
(10,'ATH-REAL-OCTOPUS','Βελούδινο Χταποδάκι','Velvet Octopus Plushie','Ένα υπερ-μαλακό χειροποίητο χταποδάκι, σχεδιασμένο για αγκαλιές, παιχνίδι και πολλή χαριτωμένη προσωπικότητα.\n\n\n\nΥπέροχη επιλογή για λάτρεις της θάλασσας, συλλέκτες χειροποίητων ή για μια ζεστή γωνιά σε παιδικό δωμάτιο.\n\n\n\nΕπιλογή προσαρμογής: μπορείτε να ζητήσετε το χρώμα που προτιμάτε.\n\n\n\nΥλικό: Νήμα velvet.\n\n\n\nΣημαντικό: Τα μικρά κομμάτια και τα ματάκια σε αυτό το λούτρινο απαιτούν επίβλεψη από γονείς για μωρά και μικρά παιδιά.\n\n\n\nΑποποίηση ευθύνης: Οι φωτογραφίες αποτελούν μια κατά προσέγγιση απεικόνιση του τελικού χρώματος. Λόγω διαφορών στα υλικά, στις ρυθμίσεις των ψηφιακών οθονών και στις παραλλαγές παραγωγής, δεν μπορούμε να εγγυηθούμε ότι το χρώμα που βλέπετε στην οθόνη σας είναι ακριβώς το πραγματικό χρώμα του προϊόντος.','A super soft handmade octopus plushie designed to feel cuddly, playful, and full of character.\n\n\n\nA lovely gift for sea-life fans, crochet collectors, or a cozy corner in a child\'s room.\n\n\n\nChoose from the ready-made velvet colourways shown in the gallery.\n\n\n\nMaterial: Velvet yarn.\n\n\n\nImportant: Small pieces and safety eyes on this plushie require parent supervision for babies and small children.\n\n\n\nDisclaimer: Our listing photos are an approximate representation of the final color. Due to substrate differences, digital screen settings, and production variations, we cannot guarantee the color you see on your screen is the true color of the product.',4,10,4,'active',0,0,NULL,'Plushies',0,'Selected colour','','Επιλεγμένο χρώμα','','','',NULL,NULL,NULL),
(11,'ATH-REAL-CHICK-HAT','Κοτοπουλάκι με Καπέλο','Chick with Hat Plushie','Γνωρίστε ένα αξιολάτρευτο χειροποίητο κοτοπουλάκι με μικρό καπέλο, βελούδινη υφή και γλυκιά χειροποίητη εμφάνιση.\n\n\n\nΙδανικό για δώρο, παιδικό δωμάτιο, διακόσμηση γραφείου ή για όποιον αγαπά τα χαριτωμένα crochet λούτρινα.\n\n\n\nΕπιλογή προσαρμογής: το χρώμα στο καπέλο μπορεί να αλλάξει κατόπιν συνεννόησης.\n\n\n\nΥλικό: Νήμα velvet.\n\n\n\nΣημαντικό: Τα μικρά κομμάτια και τα ματάκια σε αυτό το λούτρινο απαιτούν επίβλεψη από γονείς για μωρά και μικρά παιδιά.\n\n\n\nΑποποίηση ευθύνης: Οι φωτογραφίες αποτελούν μια κατά προσέγγιση απεικόνιση του τελικού χρώματος. Λόγω διαφορών στα υλικά, στις ρυθμίσεις των ψηφιακών οθονών και στις παραλλαγές παραγωγής, δεν μπορούμε να εγγυηθούμε ότι το χρώμα που βλέπετε στην οθόνη σας είναι ακριβώς το πραγματικό χρώμα του προϊόντος.','Meet an adorable handmade chick plushie with a tiny hat, a soft velvet texture, and a cheerful handmade look.\n\n\n\nPerfect for gifting, nursery shelves, desk decor, or anyone who loves cute crochet companions.\n\n\n\nFinished in the warm yellow-and-burgundy colourway shown in the photos.\n\n\n\nMaterial: Velvet yarn.\n\n\n\nImportant: Small pieces and safety eyes on this plushie require parent supervision for babies and small children.\n\n\n\nDisclaimer: Our listing photos are an approximate representation of the final color. Due to substrate differences, digital screen settings, and production variations, we cannot guarantee the color you see on your screen is the true color of the product.',5,10,4,'active',0,0,NULL,'Plushies',0,'','','','','','',NULL,NULL,NULL),
(12,'ATH-REAL-SPONGEBOB','Λούτρινο SpongeBob','SpongeBob Crochet Plushie','Ένα χειροποίητο λούτρινο εμπνευσμένο από τον SpongeBob, με έντονες λεπτομέρειες, απαλή υφή και πολύ χαρακτήρα.\n\n\n\nΙδανικό για fans καρτούν, θεματικά δώρα ή για όποιον θέλει ένα ξεχωριστό χειροποίητο κομμάτι.\n\n\n\nΥλικό: Νήμα velvet.\n\n\n\nΣημαντικό: Τα μικρά κομμάτια και τα ματάκια σε αυτό το λούτρινο απαιτούν επίβλεψη από γονείς για μωρά και μικρά παιδιά.\n\n\n\nΑποποίηση ευθύνης: Οι φωτογραφίες αποτελούν μια κατά προσέγγιση απεικόνιση του τελικού χρώματος. Λόγω διαφορών στα υλικά, στις ρυθμίσεις των ψηφιακών οθονών και στις παραλλαγές παραγωγής, δεν μπορούμε να εγγυηθούμε ότι το χρώμα που βλέπετε στην οθόνη σας είναι ακριβώς το πραγματικό χρώμα του προϊόντος.','A handmade SpongeBob-inspired crochet plushie with bold details, soft texture, and lots of character.\n\n\n\nPerfect for cartoon fans, themed gifts, or anyone who wants a fun handmade statement piece.\n\n\n\nMaterial: Velvet yarn.\n\n\n\nImportant: Small pieces and safety eyes on this plushie require parent supervision for babies and small children.\n\n\n\nDisclaimer: Our listing photos are an approximate representation of the final color. Due to substrate differences, digital screen settings, and production variations, we cannot guarantee the color you see on your screen is the true color of the product.',2,12,5,'low_stock',0,0,NULL,'Characters',0,'','','','','','',NULL,NULL,NULL),
(13,'ATH-REAL-PATRICK','Λούτρινος Patrick Star','Patrick Star Crochet Plushie','Ένα απαλό χειροποίητο λούτρινο εμπνευσμένο από τον Patrick, με παιχνιδιάρικο σχήμα και cozy crochet τελείωμα.\n\n\n\nΤαιριάζει υπέροχα σε fans καρτούν, θεματικά δώρα ή σε μια ξεχωριστή συλλογή χειροποίητων.\n\n\n\nΥλικό: Νήμα velvet.\n\n\n\nΣημαντικό: Τα μικρά κομμάτια και τα ματάκια σε αυτό το λούτρινο απαιτούν επίβλεψη από γονείς για μωρά και μικρά παιδιά.\n\n\n\nΑποποίηση ευθύνης: Οι φωτογραφίες αποτελούν μια κατά προσέγγιση απεικόνιση του τελικού χρώματος. Λόγω διαφορών στα υλικά, στις ρυθμίσεις των ψηφιακών οθονών και στις παραλλαγές παραγωγής, δεν μπορούμε να εγγυηθούμε ότι το χρώμα που βλέπετε στην οθόνη σας είναι ακριβώς το πραγματικό χρώμα του προϊόντος.','A soft handmade Patrick-inspired plushie with a playful shape and a cozy crochet finish.\n\n\n\nGreat for cartoon lovers, themed gifts, or adding a bit of fun personality to a handmade collection.\n\n\n\nMaterial: Velvet yarn.\n\n\n\nImportant: Small pieces and safety eyes on this plushie require parent supervision for babies and small children.\n\n\n\nDisclaimer: Our listing photos are an approximate representation of the final color. Due to substrate differences, digital screen settings, and production variations, we cannot guarantee the color you see on your screen is the true color of the product.',2,12,5,'low_stock',0,0,NULL,'Characters',0,'','','','','','',NULL,NULL,NULL);
